let state;try{state=JSON.parse(localStorage.getItem('nihongo-path')||'{}')}catch{state={}}state={lang:'bn',level:'N5',saved:[],learned:[],dark:false,...state};let page='home',kind='grammar',query='',limit=30,filter='all',db={},levelExtras={},current=null,reviewMode='flash',cardIndex=0,flipped=false,score=0,answered=false;
