function nav(){const hrefs={home:'index.html',learn:'lessons.html',review:'review.html',progress:'progress.html'};for(const id of ['#sideNav','#bottom'])$(id).innerHTML=['home','learn','review','progress'].map((p,i)=>`<a class="navitem ${(page===p||(page==='level'&&p==='learn'))?'active':''}" href="${hrefs[p]}" ${page===p||(page==='level'&&p==='learn')?'aria-current="page"':''}><span>${['⌂','▤','↻','◴'][i]}</span> ${t()[p]}</a>`).join('')}
function levels(){return `<div class="levels">${LEVELS.map((n,i)=>{let d=db[n],count=state.learned.filter(k=>k.includes(':'+n+':')).length;return `<a href="${n.toLowerCase()}.html" class="level ${page==='learn'&&state.level===n?'selected':''}" data-level="${n}"><span class="levelmark">${['芽','葉','花','樹','森'][i]}</span><strong>${n}</strong><span class="label">${t().levelnames[i]}</span><p>${(d.vocab.length-(levelExtras[n]||0)).toLocaleString()} ${t().vocab}${levelExtras[n]?` + ${levelExtras[n].toLocaleString()} ${t().extra}`:''}<br>${d.grammar.length} ${t().grammar} · ${d.kanji.length} ${t().kanji}</p><div class="progressbar"><i style="width:${count/(d.vocab.length+d.grammar.length+d.kanji.length)*100}%"></i></div></a>`}).join('')}</div>`}
function bindLevels(){ /* Real links intentionally allow full page navigation and Auto ads eligibility. */ }
function render(){document.documentElement.lang=state.lang;document.body.classList.toggle('dark',state.dark);$('#language').value=state.lang;nav();if(page==='home'){let w=db[state.level].vocab[new Date().getDate()%db[state.level].vocab.length];$('#main').innerHTML=`<section class="hero"><div><span class="eyebrow">${t().eyebrow}</span><h1>${t().title.replace('\n','<br>')}</h1><p>${t().sub}</p><button class="primary" id="start">${t().start}</button></div><div class="hero-art">学</div></section><div class="sectionhead"><h2>${t().choose}</h2><small>N5 → N1</small></div>${levels()}<div class="sectionhead"><h2>${t().continue}</h2><small>少しずつ、毎日。</small></div><div class="twocol"><section class="panel"><span class="eyebrow">${t().word}</span><div class="big-jp">${esc(w.word)}</div><div class="muted">${esc(w.reading)} · ${esc(w.romaji)}</div><p>${esc(words[w.word]&&state.lang!=='en'?words[w.word][state.lang==='bn'?0:1]:w.meanings.join('; '))}</p><button class="chip" id="dailyListen">▷ ${t().listen}</button></section><section class="panel"><span class="eyebrow">${t().progress}</span><div class="stat">${state.learned.length}</div><p>${t().learned} · ${state.saved.length} ${t().saved}</p><div class="muted">${Object.values(db).reduce((a,d)=>a+d.vocab.length,0).toLocaleString()} ${t().vocab} · ${Object.values(db).reduce((a,d)=>a+d.grammar.length,0)} ${t().grammar}</div></section></div>`;$('#start').onclick=()=>{page='learn';render()};$('#dailyListen').onclick=ev=>speak(w.word,ev.currentTarget)}else if(page==='learn'){renderCatalog()}else if(page==='level'){renderLevelPage()}else if(page==='review')review();else progress();bindLevels()}
function entries(){return db[state.level][kind].filter(e=>(filter==='all'||(filter==='extra'?e.curriculum_status==='supplementary':filter==='core'?e.curriculum_status!=='supplementary':state[filter].includes(key(e))))&&(!query||JSON.stringify([e.word,e.pattern,e.reading,e.romaji,e.other_forms,e.meaning,e.meanings,meaning(e)]).toLowerCase().includes(query.toLowerCase())))}
function results(){let rows=entries();$('#results').innerHTML=`<div class="sectionhead"><h2>${state.level} · ${t()[kind]}</h2><small>${rows.length} items</small></div><div class="cards">${rows.slice(0,limit).map(e=>`<button class="entry" data-entry="${esc(e.id)}"><span class="saved">${state.saved.includes(key(e))?'★':''}${state.learned.includes(key(e))?' ✓':''}</span><b>${esc(e.word||e.pattern)}</b><small>${esc(e.reading||e.romaji)}</small><p>${esc(meaning(e))}</p>${e.curriculum_status==='supplementary'?`<small class="translation-tag">${t().extra}</small>`:''}</button>`).join('')}</div>${!rows.length?`<p class="empty">${t().empty}</p>`:''}${rows.length>limit?`<button class="chip load" id="load">${t().more} (${rows.length-limit})</button>`:''}`;document.querySelectorAll('[data-entry]').forEach(b=>b.onclick=()=>openEntry(rows.find(e=>e.id===b.dataset.entry)));if($('#load'))$('#load').onclick=()=>{limit+=30;results()}}
function speak(s,button){window.NihongoSpeech.play(s,button)}
function progress(){$('#main').innerHTML=`<span class="eyebrow">ONE STEP AT A TIME</span><h1>${t().progress}</h1><div class="twocol"><div class="panel"><div class="stat">${state.learned.length}</div><p>${t().learned}</p></div><div class="panel"><div class="stat">${state.saved.length}</div><p>${t().saved}</p></div></div><div class="sectionhead"><h2>${t().choose}</h2></div>${levels()}<p class="notice">Progress is saved on this browser. Clearing browser data removes it. No account or cloud sync is enabled.</p>`}
$('#language').onchange=e=>{state.lang=e.target.value;persist();render()};$('#more').onclick=()=>$('#menu').hidden=!$('#menu').hidden;$('#theme').onclick=()=>{state.dark=!state.dark;persist();render();$('#menu').hidden=true};$('.close').onclick=()=>{$('#detail').close();render()};$('#detail').onclick=e=>{if(e.target===$('#detail')){$('#detail').close();render()}};$('#reset').onclick=()=>{if(confirm('Reset all saved lessons and learning progress?')){state.saved=[];state.learned=[];persist();render()}$('#menu').hidden=true};
async function loadLevel(n){if(Array.isArray(db[n]?.vocab))return;const r=await fetch('data/'+n.toLowerCase()+'.json?v='+CONTENT_VERSION);if(!r.ok)throw Error(n);db[n]=await r.json()}
$('#main').innerHTML='<p class="empty">日本語 · Loading lessons…</p>';
(async()=>{const response=await fetch('data/index.json?v='+CONTENT_VERSION);if(!response.ok)throw Error('index');const index=await response.json();for(const n of LEVELS){levelExtras[n]=index[n].extra_vocab||0;db[n]=Object.fromEntries(['vocab','grammar','kanji'].map(k=>[k,{length:index[n][k]}]));}await loadLevel(state.level);render()})().catch(()=>{$('#main').innerHTML='<p class="empty">Could not load lessons. Please refresh to retry.</p>'});
