function local(e){return state.lang==='en'?null:e.locales?.[state.lang]}
meaning=function(e,itemKind=kind){return local(e)?.meaning||e.meaning||e.meanings?.join('; ')||''};
const baseRender=render;render=function(){baseRender();for(const [id,label] of [['theme','theme'],['sources','about'],['reset','reset'],['adSettings','adSettings']])$('#'+id).textContent=t()[label];window.updateAdLabel?.(state.lang);document.querySelectorAll('.notice').forEach(p=>{if(!p.textContent.trim())p.remove()});if(page==='home'){let w=db[state.level].vocab[new Date().getDate()%db[state.level].vocab.length];let card=$('#dailyListen').closest('section');card.querySelector('p').textContent=meaning(w,'vocab')}if(page==='progress')$('#main .notice').textContent=t().localProgress};
openEntry=function(e){current=e;const k=key(e),l=local(e);$('#detailBody').innerHTML=`<span class="eyebrow">${e.level} · ${t()[kind]}</span><h1>${esc(e.word||e.pattern)}</h1>${e.reading?`<p>${esc(e.reading)}</p>`:''}<h2>${esc(meaning(e))}</h2>${e.curriculum_status==='supplementary'?`<p class="notice">${t().extraNote}</p>`:''}${e.source_review_status==='community-reference'?`<p class="translation-tag">${t().communityReference} · <a href="https://hanabira.org">Hanabira</a></p>`:''}${state.lang!=='en'&&local(e)?.translation_method?.includes('machine')?`<p class="translation-tag">${t().autoTranslation}</p><p class="source-line">${esc(e.meaning||e.meanings?.join('; '))}</p>`:''}<div class="actions"><button class="chip" id="listen">▷ ${t().listen}</button><button class="chip" id="save">${state.saved.includes(k)?'★':'☆'} ${t().save}</button><button class="chip" id="done">${state.learned.includes(k)?'✓ ':''}${t().done}</button></div>${kind==='kanji'?`<p class="stroke-count">${e.strokes} ${t().strokes}</p><div class="kanji-readings"><div class="example"><b>${t().onyomi}</b><p>${esc(e.onyomi.join(' · ')||'—')}</p></div><div class="example"><b>${t().kunyomi}</b><p>${esc(e.kunyomi.join(' · ')||'—')}</p></div></div>`:''}${e.formation?`<h3>${t().formation}</h3><div class="example">${esc(l?.formation||e.formation)}</div>`:''}${l?.guidance?`<h3>${t().guidance}</h3><div class="tip">${esc(l.guidance)}</div>`:''}${e.examples.length?`<h3>${t().examples}</h3>${e.examples.map((x,i)=>`<div class="example"><b>${esc(x.ja)}</b><p>${esc(l?.examples[i]||x.en)}</p>${state.lang!=='en'&&l?.example_methods?.[i]!=='authored'?`<small class="translation-tag">${t().autoTranslation}</small><p class="source-line">${esc(x.en)}</p>`:''}<button class="chip example-audio" data-speak="${i}">▷ ${t().listen}</button></div>`).join('')}`:''}${state.lang==='en'&&e.notes?`<h3>${t().notes}</h3><p>${esc(e.notes)}</p>`:''}<details class="source-details"><summary>${t().original}</summary><p>${esc(e.meaning||e.meanings?.join('; '))}</p>${e.formation?`<p>${esc(e.formation)}</p>`:''}${e.notes?`<p>${esc(e.notes)}</p>`:''}${e.examples.map(x=>`<div class="example"><b>${esc(x.ja)}</b><p>${esc(x.en)}</p></div>`).join('')}</details>`;$('#listen').onclick=ev=>speak(e.word||e.examples[0]?.ja||e.pattern,ev.currentTarget);document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=ev=>speak(e.examples[+b.dataset.speak].ja,ev.currentTarget));for(const [id,list] of [['save','saved'],['done','learned']])$('#'+id).onclick=()=>{state[list]=state[list].includes(k)?state[list].filter(x=>x!==k):[...state[list],k];persist();openEntry(e)};if(!$('#detail').open)$('#detail').showModal()};
review=function(){let list=db[state.level].vocab;const saved=list.filter(e=>state.saved.includes('vocab:'+e.level+':'+e.id));if(saved.length)list=saved;const e=list[cardIndex%list.length];$('#main').innerHTML=`<span class="eyebrow">${state.level}</span><h1>${t().review}</h1><div class="toolbar"><button class="chip ${reviewMode==='flash'?'active':''}" id="flash">${t().flash}</button><button class="chip ${reviewMode==='quiz'?'active':''}" id="quiz">${t().quiz}</button><select id="reviewLevel" aria-label="Review level">${LEVELS.map(n=>`<option ${state.level===n?'selected':''}>${n}</option>`).join('')}</select></div><section class="panel flash"><span class="eyebrow">${cardIndex%list.length+1} / ${list.length}</span><div class="big-jp">${esc(e.word)}</div><p>${esc(e.reading)}</p>${e.curriculum_status==='supplementary'?`<small class="translation-tag">${t().extraNote}</small>`:''}${reviewMode==='flash'?`<p>${flipped?esc(meaning(e,'vocab')):'•••'}</p>${flipped&&state.lang!=='en'?`<small class="translation-tag">${t().autoTranslation}</small><p class="source-line">${esc(e.meanings.join('; '))}</p>`:''}<button class="primary" id="flip">${flipped?t().next:t().flip}</button>`:`<div id="answers"></div><p id="feedback" role="status"></p><button class="primary" id="nextQuestion" hidden>${t().next}</button>`}</section><p class="notice">${saved.length?t().saved:t().practice}</p>`;$('#flash').onclick=()=>{reviewMode='flash';review()};$('#quiz').onclick=()=>{reviewMode='quiz';review()};$('#reviewLevel').onchange=async x=>{const n=x.target.value;x.target.disabled=true;try{await loadLevel(n);state.level=n;cardIndex=0;flipped=false;persist();review()}catch{$('#main').innerHTML='<p class="empty">Could not load this level. Please refresh to retry.</p>'}};if(reviewMode==='flash')$('#flip').onclick=()=>{if(flipped)cardIndex++;flipped=!flipped;review()};else{answered=false;const wrong=db[state.level].vocab.filter(x=>x.id!==e.id&&meaning(x,'vocab')!==meaning(e,'vocab')).sort(()=>Math.random()-.5).slice(0,3),opts=[e,...wrong].sort(()=>Math.random()-.5);$('#answers').innerHTML=opts.map((o,i)=>`<button class="answer" data-answer="${i}">${esc(meaning(o,'vocab'))}</button>`).join('');document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(answered)return;answered=true;const ok=opts[+b.dataset.answer].id===e.id;b.classList.add(ok?'correct':'incorrect');document.querySelectorAll('[data-answer]').forEach(a=>{a.disabled=true;if(opts[+a.dataset.answer].id===e.id)a.classList.add('correct')});$('#feedback').textContent=ok?'✓ '+t().correct:t().incorrect+': '+meaning(e,'vocab');$('#nextQuestion').hidden=false});$('#nextQuestion').onclick=()=>{cardIndex++;review()}}};
$('#sources').onclick=()=>{$('#menu').hidden=true;const total=k=>Object.values(db).reduce((a,d)=>a+d[k].length,0);const text={bn:['বাংলা ও নেপালির কিছু grammar অর্থ এই app-এর জন্য লেখা হয়েছে; নতুন কিছু পাঠে স্বয়ংক্রিয় অনুবাদের খসড়া আছে। Vocabulary, Kanji-এর অর্থ এবং উদাহরণে offline স্বয়ংক্রিয় অনুবাদের খসড়া আছে; মূল শব্দগুলোর কিছু সংশোধন করা হয়েছে। সব অনুবাদ এখনো স্থানীয় ভাষাবিদ দিয়ে যাচাই করা হয়নি। মূল Japanese ও English পাঠ প্রতিটি lesson-এ পাওয়া যায়।','লেভেলগুলো কমিউনিটির আনুমানিক তালিকা; এটি official JLPT-এর সম্পূর্ণ syllabus নয়।'],ne:['बङ्गाली र नेपालीका केही व्याकरण अर्थ लेखिएका छन्; नयाँ पाठमा चिन्ह लगाइएका स्वचालित मस्यौदा पनि छन्। शब्दावली, कान्जीका अर्थ र उदाहरणमा अफलाइन स्वचालित अनुवादका मस्यौदा छन्; केही आधारभूत शब्द सच्याइएका छन्। सबै अनुवादको मातृभाषी समीक्षा भएको छैन। हरेक पाठमा मूल जापानी र अंग्रेजी हेर्न सकिन्छ।','स्तरहरू समुदायको अनुमानित सूचीमा आधारित छन्; यो आधिकारिक JLPT को सम्पूर्ण पाठ्यक्रम होइन।'],en:['Some grammar glosses are authored in Bangla and Nepali; newly added lessons include labeled machine drafts. Vocabulary, Kanji glosses and examples include offline machine translation drafts with curated core corrections. Full native-speaker review is outstanding. Original Japanese and English remain available in every lesson.','Community level assignments are approximate. This is not an official or exhaustive JLPT syllabus.']}[state.lang];$('#detailBody').innerHTML=`<h1>${t().source}</h1><p>Nihongo Path · Hossain Najmul</p><p>N5–N1 · ${total('vocab').toLocaleString()} ${t().vocab} · ${total('grammar')} ${t().grammar} · ${total('kanji').toLocaleString()} ${t().kanji}</p><p>${text[0]}</p><p>${text[1]}</p><p><a href="https://github.com/evanclan/OpenJLPT" target="_blank" rel="noopener">OpenJLPT ↗</a> · <a href="https://github.com/jkindrix/japanese-language-data" target="_blank" rel="noopener">Japanese Language Data ↗</a></p><p><a href="data/NOTICE.md">OpenJLPT attribution</a> · <a href="data/SUPPLEMENT-ATTRIBUTION.md">Supplement attribution</a> · <a href="data/LICENSE">CC BY-SA 4.0</a> · <a href="coverage.html">Coverage & study resources</a> · <a href="data/audit.json">Data audit</a> · <a href="data/reference-audit.json">Extended reference audit</a> · <a href="data/HANABIRA-ATTRIBUTION.md">Hanabira attribution</a></p><p><a href="https://huggingface.co/alirezamsh/small100">SMaLL-100</a> · <a href="data/TRANSLATION-MODEL-LICENSE">MIT license</a></p><p>${t().localProgress}</p><p><a href="privacy.html">${t().adSettings}</a></p>`;$('#detail').showModal()};
$('#adSettings').onclick=()=>{$('#menu').hidden=true;const info={bn:['AdSense Auto ads code যুক্ত হয়েছে।','প্রকাশক: ca-pub-3728341118830943','এই site-এর Google approval ও Auto ads চালুর অবস্থা যাচাই করা হয়নি। বিজ্ঞাপন আসা নিশ্চিত নয়। নতুন responsive ad unit Nihongo Path - Responsive Lessons (2007625275) যুক্ত হয়েছে।','Website GitHub Pages-এ public। AdSense domain ownership verification ও review এখনো বাকি।'],ne:['AdSense Auto ads कोड जोडिएको छ।','प्रकाशक: ca-pub-3728341118830943','यो साइटको Google स्वीकृति र Auto ads स्थिति जाँचिएको छैन। विज्ञापन आउने ग्यारेन्टी छैन। नयाँ responsive ad unit Nihongo Path - Responsive Lessons (2007625275) जोडिएको छ।','GitHub Pages वेबसाइट सार्वजनिक छ। AdSense domain ownership verification र समीक्षा बाँकी छन्।'],en:['AdSense Auto ads code is installed.','Publisher: ca-pub-3728341118830943','Google site approval and Auto ads settings have not been verified. Ad delivery is not guaranteed. The dedicated responsive ad unit Nihongo Path - Responsive Lessons (2007625275) is installed.','The GitHub Pages website is public. AdSense domain ownership verification and review remain pending.']}[state.lang];$('#detailBody').innerHTML=`<h1>${t().adSettings}</h1>${info.map(x=>`<p>${esc(x)}</p>`).join('')}<p><a href="privacy.html">Privacy & advertising ↗</a></p>`;$('#detail').showModal()};

Object.assign(T.bn,{autoTranslation:'স্বয়ংক্রিয় অনুবাদ · মূল বাক্যের সঙ্গে মিলিয়ে পড়ুন'});Object.assign(T.ne,{autoTranslation:'स्वचालित अनुवाद · मूल वाक्यसँग तुलना गर्नुहोस्'});Object.assign(T.en,{autoTranslation:'Automatic translation draft'});

// Separate documents give each level a shareable URL and preserve normal link navigation.
const routeFile=location.pathname.split('/').pop().toLowerCase();
const levelRoute=/^n([1-5])\.html$/.exec(routeFile);
if(levelRoute){page='level';state.level='N'+levelRoute[1];kind=new URLSearchParams(location.search).get('section')||'grammar';if(!['grammar','vocab','kanji'].includes(kind))kind='grammar';persist()}
else page=({'lessons.html':'learn','review.html':'review','progress.html':'progress'})[routeFile]||'home';
Object.assign(T.bn,{backLevels:'সব লেভেল',levelIntro:'এই লেভেলের সব পাঠ বিষয় অনুযায়ী সাজানো আছে।',openLevel:'লেভেল খুলুন →'});
Object.assign(T.en,{backLevels:'All levels',levelIntro:'All lessons for this level, organized by subject.',openLevel:'Open level →'});
Object.assign(T.ne,{backLevels:'सबै स्तर',levelIntro:'यस स्तरका सबै पाठ विषयअनुसार मिलाइएका छन्।',openLevel:'स्तर खोल्नुहोस् →'});
function renderCatalog(){
 $('#main').innerHTML=`<span class="eyebrow">${t().path}</span><h1>${t().learn}</h1><p>${t().choose}</p>${levels()}`;
}
function renderLevelPage(){
 const d=db[state.level];
 $('#main').innerHTML=`<a class="back-link" href="lessons.html">← ${t().backLevels}</a><span class="eyebrow">${t().path}</span><h1>${state.level} · ${t().levelnames[LEVELS.indexOf(state.level)]}</h1><p>${t().levelIntro}</p>${kind==='vocab'&&levelExtras[state.level]?`<p class="notice">${levelExtras[state.level].toLocaleString()} ${t().extra} · ${t().extraNote}</p>`:''}${state.lang!=='en'?`<p class="notice">${t().autoTranslation}</p>`:''}<div class="subject-links">${['grammar','vocab','kanji'].map(k=>`<a class="subject ${k===kind?'active':''}" ${k===kind?'aria-current="page"':''} href="${state.level.toLowerCase()}.html?section=${k}"><strong>${d[k].length.toLocaleString()}</strong><span>${t()[k]}</span></a>`).join('')}</div><div class="toolbar"><input id="search" aria-label="Search" placeholder="${t().search}" value="${esc(query)}"></div><div class="toolbar">${(kind==='vocab'&&levelExtras[state.level]?['all','core','extra','saved','learned']:['all','saved','learned']).map(x=>`<button class="chip ${filter===x?'active':''}" data-filter="${x}">${t()[x]}</button>`).join('')}</div><div id="results"></div>`;
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;limit=30;render()});
 $('#search').oninput=e=>{query=e.target.value;limit=30;results()};results();
 document.title=`${state.level} ${t()[kind]} · Nihongo Path`;
}
const renderWithRoutes=render;
render=function(){renderWithRoutes();document.querySelectorAll('a.brand').forEach(a=>a.href='index.html');if(page==='home'&&$('#start'))$('#start').outerHTML=`<a id="start" class="primary" href="${state.level.toLowerCase()}.html">${t().start}</a>`};
const adSettingsBase=$('#adSettings').onclick;
$('#adSettings').onclick=()=>{adSettingsBase();const note={bn:'পৃষ্ঠা বদলের বিজ্ঞাপন: AdSense → Ads → আপনার site → Overlay formats → Vignette ads চালু করে Apply to site দিন। লেভেল কার্ডগুলো এখন সরাসরি page link। বিজ্ঞাপন দেখাবে কি না ও কত ঘনঘন দেখাবে, Google নিয়ন্ত্রণ করে; প্রতিবার দেখানো নিশ্চিত নয়।',en:'Between-page ads: in AdSense, go to Ads → your site → Overlay formats → enable Vignette ads → Apply to site. Level cards are now normal page links. Google controls ad delivery and frequency; an ad is not guaranteed on every tap.',ne:'पृष्ठबीचको विज्ञापन: AdSense → Ads → आफ्नो site → Overlay formats → Vignette ads सक्षम गर्नुहोस् → Apply to site। स्तर कार्डहरू सामान्य पृष्ठ लिंक हुन्। विज्ञापन र आवृत्ति Google ले नियन्त्रण गर्छ; हरेक पटक आउने ग्यारेन्टी छैन।'}[state.lang];$('#detailBody').insertAdjacentHTML('beforeend',`<p>${esc(note)}</p>`) };
